// secrets-veil: types.ts - shared type definitions
// Generated by OrchestKit mod build

/**
 * An entry in the mask table.
 */
export type MaskTableEntry =
  | {
      type: "env";
      name: string;
      value: string;
      pattern: string;
    }
  | {
      type: "pattern";
      pattern: string;
    };

/**
 * The mask table built at session.start from env names and patterns.
 */
export interface MaskTable {
  entries: readonly MaskTableEntry[];
}

/**
 * A span in the original text that was masked.
 * Used by the UI to create hover-reveal overlays.
 */
export interface MaskSpan {
  /** Start position in original text */
  start: number;
  /** End position in original text */
  end: number;
  /** The original value that was masked */
  value: string;
  /** The env var name, if applicable */
  name?: string;
}

/**
 * Result of masking text.
 */
export interface MaskResult {
  /** The masked text (with secrets replaced by bullets) */
  text: string;
  /** Spans indicating where secrets were found */
  spans: MaskSpan[];
}

/**
 * Revealed secrets tracker (module-scope, keyed by requestId).
 */
export interface RevealedState {
  /** Set of requestIds that have been revealed */
  revealed: Set<string>;
}

/**
 * The $ dependency object (subset used by secrets-veil).
 * Mocked in tests with a plain object.
 */
export interface DollarAPI {
  env: {
    get(name: string): Promise<string | undefined>;
  };
  ui: {
    invalidate(event: "ui.render"): void;
    log(message: string): void;
    notice(id: string, message: string): void;
  };
  clock?: {
    every(ms: number, callback: () => void | Promise<void>): void;
  };
}

/**
 * Event types for function hooks.
 */
export interface ToolCallEvent {
  tool: string;
  args: Record<string, unknown>;
  requestId: string;
}

export interface ToolCallResult {
  deny?: { reason: string };
  result?: unknown;
  text?: string;
  isError?: boolean;
  context?: string[];
}

export interface UIRenderEvent {
  component: string;
  requestId?: string;
}

export interface CommandRegisterEvent {
  command: string;
}

export interface UIPressEvent {
  requestId: string;
}

export interface SessionStartEvent {
  surface?: "terminal" | "desktop" | "mobile";
  isInteractive?: boolean;
}

/**
 * The next() function signature.
 */
export type NextFn<E> = (event: E) => Promise<ToolCallResult | void>;
